  const resumeOriginalDraft=()=>run('Comprobando borrador…',async()=>{if(!recoveredOriginal||!pdf)return;const old=recoveredOriginal;if(old.edit.source!==await recoverySource(bytes))throw new Error('El PDF base cambió. Copia el texto del borrador y vuelve a seleccionar su destino.');const analysis=await inspectOriginalText(bytes,old.draft.page),runs=old.draft.paragraph?analysis.paragraphs:old.draft.indices?analysis.lines:analysis.objects,target=runs.find(r=>r.index===old.draft.index&&r.text===old.draft.text&&JSON.stringify(r.indices)===JSON.stringify(old.draft.indices));if(!target?.editable)throw new Error('La selección original ya no es compatible. El borrador se conserva para copiarlo.');const p=await pdf.getPage(old.draft.page),draft=makeOriginalDraft({...target,directEditing:old.draft.directEditing},{source:analysis.source,page:old.draft.page,unit:p.userUnit});setSection('Editar PDF');setViewMode('continuous');setOriginalMode(old.draft.directEditing?'cursor':old.draft.paragraph?'paragraphs':old.draft.indices?'lines':'fragments');setOriginalSession({...old,draft,edit:{...originalEdit(draft),...Object.fromEntries(['text','font','fontSize','color','spans','selection','formatUndo','allowOverflow','expandToSpace','fitMinimum','paragraphWidth','paragraphHeight','paragraphOffsetX','paragraphOffsetY','paragraphAutoGrow','paragraphSpace','lineSpacing','align','indentLeft','indentRight','firstLineIndent','spaceBefore','spaceAfter'].filter(key=>(old.edit as any)[key]!==undefined).map(key=>[key,(old.edit as any)[key]]))}});setRecoveredOriginal(null);setDialog(old.surface==='dialog'?'original-text':'');go(old.draft.page);});
  const resumeProperty=(entry:any)=>{if(entry.kind==='form'){const field=designFields.find(f=>f.id===entry.id);if(!field||JSON.stringify(field)!==entry.base){onError('El campo cambió. Conserva o copia el borrador antes de descartarlo.');return;}setSection('Formularios');setFormMode('design');setFieldKind(null);setSelectedField(entry.id);setSide('forms');setSidebar(true);setViewMode('continuous');go(field.page);}else{const marks=model.marks.filter(m=>entry.ids.includes(m.id));if(annotationDraftBase(marks)!==entry.base){onError('La anotación cambió. El borrador se conserva para consultarlo.');return;}setSelection(entry.ids);setSection('Anotar');setSide('properties');setSidebar(true);setTool('select');go(marks[0].page);}setDialog('');requestAnimationFrame(()=>{const panel=scroll.current?.closest('.workspace')?.querySelector<HTMLElement>(entry.kind==='form'?'.field-properties':'.annotation-properties');panel?.scrollIntoView({block:'nearest'});panel?.querySelector<HTMLElement>('input')?.focus({preventScroll:true});});};
