    <div className="ribbon-tabs"><div>{['Lectura','Editar PDF','Anotar','Organizar','Formularios'].map(s=><button key={s} className={section===s?'selected':''} disabled={!!originalSession||originalMoving} onClick={()=>{setSection(s);if(s==='Editar PDF')startOriginalEdit();if(s==='Lectura'||s==='Formularios')setTool('select');if(s==='Formularios'){setViewMode('continuous');setSidebar(true);setSide('forms');}}}>{tr(s)}</button>)}</div><Button disabled={!!busy||!!originalSession||originalMoving} onClick={()=>setDialog('recovery-drafts')}>{tr("Borradores pendientes")}{draftBundle||ocrReview||tableDraft?' · '+(propertyDrafts.length+((pendingOriginal&&originalSession)||recoveredOriginal?1:0)+(pendingMark?1:0)+(ocrReview?1:0)+(tableDraft?1:0)):''}</Button><Button disabled={!pdf||!!busy||!!originalSession||originalMoving} active={aiOpen} onClick={()=>setAiOpen(!aiOpen)}>{tr("Asistente IA")}</Button><span className="document-type">{tr("PDF ")}{encrypted&&<LockKeyhole size={13}/>}</span><Button icon={Save} onClick={()=>save()} disabled={!canEdit||!!busy} className="primary">{tr("Guardar como")}</Button></div>
