      {section==='Organizar'&&<><Button icon={RotateCw} onClick={()=>beginOperation('rotate')} disabled={!canEdit}>{tr("Rotar")}</Button><Button icon={Files} onClick={()=>beginOperation('merge')} disabled={!canEdit}>{tr("Combinar")}</Button><Button icon={Scissors} onClick={()=>beginOperation('extract')} disabled={!canEdit}>{tr("Extraer")}</Button><Button icon={List} onClick={()=>setDialog('organizer')} disabled={!canEdit}>{tr("Reordenar")}</Button><Button icon={FilePlus2} onClick={()=>beginOperation('blank')} disabled={!canEdit}>{tr("Insertar")}</Button><Button icon={Trash2} onClick={()=>beginOperation('delete')} disabled={!canEdit}>{tr("Eliminar")}</Button><span className="tool-divider"/><Button icon={Crop} title={tr("Recortar márgenes")} onClick={()=>setDialog('visual-crop')} disabled={!canEdit}/><Button icon={Stamp} title={tr("Marca de agua")} onClick={()=>beginOperation('watermark')} disabled={!canEdit}/><Button icon={Hash} title={tr("Numerar páginas")} onClick={()=>beginOperation('numbers')} disabled={!canEdit}/></>}
